k=np.arange(1,21);obs=np.array([.284,.241,.213,.198,.186,.178,.169,.162,.157,.152,.148,.143,.139,.135,.131,.127,.124,.122,.120,.118]);phi=obs[1]/obs[0];geo=obs[0]*phi**(k-1);d=-np.log(obs[-1]/obs[0])/np.log(20);power=obs[0]*k**(-d);ax.plot(k,obs,'o',color=ACCENT,label='observed |return| ACF');ax.plot(k,geo,color=BAD,label='geometric fit');ax.plot(k,power,color=GOOD,label='power-law fit');ax.set_xlabel('lag (trading days)');ax.set_ylabel('ACF (unitless)');ax.set_title('Decay shape is a model-selection clue',loc='left');ax.legend(fontsize=7)
